B=Path(__file__).resolve().parent;phase=sys.argv[1];runid=int(sys.argv[2]);assert phase in ['prepare','publish'];c=json.loads((B/'publisher-controller.json').read_text())
def api(path):return json.loads(subprocess.check_output(['gh','api','repos/Richarddavis47/dtos/'+path],text=True))
